import * as React from "react";
import { cn } from "@/lib/utils";

export type SkeletButtonVariant = "primary" | "secondary" | "ghost";
export type SkeletButtonSize = "sm" | "md" | "lg";

export interface SkeletButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: SkeletButtonVariant;
  size?: SkeletButtonSize;
  evidenceUri?: string;
}

const variants: Record<SkeletButtonVariant, string> = {
  primary: "bg-foreground text-background hover:opacity-90",
  secondary: "border border-input bg-background hover:bg-muted",
  ghost: "hover:bg-muted",
};

const sizes: Record<SkeletButtonSize, string> = {
  sm: "h-8 px-3 text-xs",
  md: "h-9 px-4 text-sm",
  lg: "h-10 px-6 text-base",
};

export function SkeletButton({
  variant = "primary",
  size = "md",
  evidenceUri,
  className,
  ...props
}: SkeletButtonProps): React.JSX.Element {
  return (
    <button
      data-evidence-uri={evidenceUri}
      className={cn(
        "inline-flex items-center justify-center rounded-md font-medium transition-colors",
        "disabled:pointer-events-none disabled:opacity-50",
        variants[variant],
        sizes[size],
        className,
      )}
      {...props}
    />
  );
}
